'use strict';
// Coche: BMW M8 GTE (2018)
// Prototipo oficial de resistencia de BMW Motorsport para las 24 Horas de Le Mans y el campeonato IMSA WeatherTech.
// - Motor 4.0L BMW TwinPower Turbo V8 con 600 CV y más de 700 Nm de par.
// - Paquete aerodinámico de máxima carga para Le Mans con difusor masivo y alerón trasero ajustable.
// - Chasis ligero de 1220 kg en fibra de carbono y cambio secuencial Xtrac de 6 marchas.
(() => {

const ATLAS_B64 = "data:image/png;base64,";

const BODY_V = "";
const BODY_I = "";
const GLASS_V = "";
const GLASS_I = "";
const WHEEL_V = "";
const WHEEL_I = "";


WGSL["mat_bmw_m8_gte"] = `// Material BMW M8 GTE:
#include mesh_vert
@group(3) @binding(0) var tAtlas: texture_2d<f32>;

fn surf(in: V2F, ff: bool) -> Surface {
  var s = surfDefault(normalize(in.nrm));
  if (!ff) { s.normal = -s.normal; }

  let id = matId(in.mat);
  let p = in.ext.xyz;
  let uv = in.uv;

  let tx = textureSample(tAtlas, sLin, uv);
  s.albedo = tx.rgb;

  if (id == 18u) {
    // Carrocería BMW Motorsport Le Mans livery
    s.metal = 0.10;
    s.rough = 0.16;
    s.coat = 0.90;
    s.ao = smoothstep(0.05, 0.45, p.y) * 0.35 + 0.65;
  } else if (id == 4u || id == 5u) {
    // Neumáticos Michelin slick de Le Mans
    s.metal = 0.02;
    s.rough = 0.68;
    s.ao = 0.90;
  } else if (id == 6u) {
    // Llantas BBS forjadas de competición
    s.metal = 0.65;
    s.rough = 0.30;
    s.coat = 0.40;
  } else if (id == 2u) {
    // Discos de freno de carbono
    s.metal = 0.85;
    s.rough = 0.25;
  } else {
    s.metal = 0.15;
    s.rough = 0.35;
  }

  return s;
}
`;

function loadAtlas() {
  if (typeof CarFactory !== 'undefined' && typeof CarFactory.createAtlasTexture === 'function') {
    return CarFactory.createAtlasTexture(ATLAS_B64, 2048, 2048, 40);
  }
  return null;
}

const CAR = {
  id: 'bmw-m8-gte-2018',
  name: 'BMW M8 GTE',
  subtitle: '2018 Le Mans & IMSA Endurance Racer · 4.0L Twin-Turbo V8 · RWD',
  specs: '1220 kg · 600 CV · Le Mans Aero Spec · Xtrac 6-speed seq · RWD',
  accent: '#1c69d4',
  physics: {
    m: 1220, Izz: 1700, L: 2.780, a: 1.400, b: 1.380, tw: 1.74, h: 0.40, R: 0.355,
    mu: 1.70, B: 11.2, C: 1.52, driveF: 0.0,
    gears: [2.78, 1.98, 1.54, 1.25, 1.04, 0.88], final: 3.40, rev: 3.0, eff: 0.96,
    cdA: 0.65, crr: 0.010, brakeF: 0.61, halfW: 1.05, front: 2.56, rear: 2.56,
    // Aero Le Mans con alta carga aerodinámica en curvas rápidas:
    clA: 0.95, aeroSplitF: 0.38,
    torqueBase: 370, torquePeak: 320, torqueDrop: 200, torquePeakStart: 0.52, torquePeakSpan: 5.2, torqueDropRpm: 7.2,
    shiftUpRpm: 7400, shiftDownRpm: 5400, revLimitRpm: 7600, maxRpm: 7800, idleRpm: 1200,
  },
  hud: { maxKmh: 340, maxRpm: 8.0, redlineRpm: 7.4 },
  wheelbase: 2.780, trackF: 1.780, trackR: 1.730, wheelR: 0.355,
  hubs: [
    [1.429, 0.355, -0.890],
    [1.429, 0.355, 0.890],
    [-1.451, 0.355, -0.865],
    [-1.451, 0.355, 0.865]
  ],
  slotBody: 0, slotWheel: [0, 0, 0, 0],
  tris: 0, _t: m4(), _t2: m4(), _t3: m4(), set: null, glass: null, atlasBG: null, fam: null,
  _z4: new Float32Array(4),
  inp: new Float64Array(2),

  build() {
    const fam = CAR.fam = mkFamily('car_bmw_m8', { src: 'mat_bmw_m8_gte', noCube: true });
    CAR.slotBody = objSlot();
    for (let i = 0; i < 4; i++) CAR.slotWheel[i] = objSlot();

    const set = CAR.set = new MeshSet(fam);
    const glass = CAR.glass = new GlassSet();

    const mb = new MeshBuilder(1 << 17);
    const gl = new MeshBuilder(1 << 14);
    const w = new MeshBuilder(1 << 16);

    const bV = b64ToF32(BODY_V), bI = b64ToU32(BODY_I);
    const gV = b64ToF32(GLASS_V), gI = b64ToU32(GLASS_I);
    const wV = b64ToF32(WHEEL_V), wI = b64ToU32(WHEEL_I);

    const nbV = bV.length / 9;
    for (let i = 0; i < nbV; i++) {
      mb.mat(bV[i*9 + 8]);
      mb.v(bV[i*9], bV[i*9+1], bV[i*9+2], bV[i*9+3], bV[i*9+4], bV[i*9+5], bV[i*9+6], bV[i*9+7]);
    }
    for (let i = 0; i < bI.length; i += 3) mb.tri(bI[i], bI[i+1], bI[i+2]);

    const ngV = gV.length / 9;
    for (let i = 0; i < ngV; i++) {
      gl.v(gV[i*9], gV[i*9+1], gV[i*9+2], gV[i*9+3], gV[i*9+4], gV[i*9+5], gV[i*9+6], gV[i*9+7]);
    }
    for (let i = 0; i < gI.length; i += 3) gl.tri(gI[i], gI[i+1], gI[i+2]);

    const nwV = wV.length / 9;
    for (let i = 0; i < nwV; i++) {
      w.mat(wV[i*9 + 8]);
      w.v(wV[i*9], wV[i*9+1], wV[i*9+2], wV[i*9+3], wV[i*9+4], wV[i*9+5], wV[i*9+6], wV[i*9+7]);
    }
    for (let i = 0; i < wI.length; i += 3) w.tri(wI[i], wI[i+1], wI[i+2]);

    CAR.tris = mb.ni / 3 + gl.ni / 3;
    set.add(mb.upload(), CAR.slotBody, 3);
    glass.add_(gl.upload(), CAR.slotBody);

    const wm = w.upload();
    CAR.tris += 4 * w.ni / 3;
    for (let i = 0; i < 4; i++) set.add(wm, CAR.slotWheel[i], 3);

    const tex = loadAtlas();
    R.drawables.push({
      draw(pass, ctx) {
        if (ctx.kind === KIND.SHADOW && ctx.cascade === 3) return;
        if (!CAR.atlasBG) {
          if (!fam.bgl3) return;
          CAR.atlasBG = G.dev.createBindGroup({ layout: fam.bgl3, entries: [{ binding: 0, resource: tex.createView() }] });
        }
        pass.setBindGroup(3, CAR.atlasBG);
        set.draw(pass, ctx);
      },
    });
    R.transparents.push(glass);

    m4ident(CAR._t);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
  },

  place(body, spin, susp) {
    const steer = CAR.inp[0];
    const t = CAR._t2;
    objPrev(CAR.slotBody).set(objModel(CAR.slotBody));
    objModel(CAR.slotBody).set(body);
    for (let i = 0; i < 4; i++) {
      const sl = CAR.slotWheel[i], h = CAR.hubs[i], left = (i & 1) === 0;
      objPrev(sl).set(objModel(sl));
      const a = -(i < 2 ? steer : 0) + (left ? PI : 0), c = Math.cos(a), sn = Math.sin(a);
      const g = left ? spin[i] : -spin[i], cg = Math.cos(g), sg = Math.sin(g);
      t[0] = c * cg; t[1] = sg; t[2] = -sn * cg; t[3] = 0;
      t[4] = -c * sg; t[5] = cg; t[6] = sn * sg; t[7] = 0;
      t[8] = sn; t[9] = 0; t[10] = c; t[11] = 0;
      t[12] = h[0]; t[13] = h[1] + susp[i]; t[14] = h[2]; t[15] = 1;
      m4mul(objModel(sl), body, t);
    }
  },
};

CARS.register(CAR);
})();
